#pragma once
#include "kstationStartupDisplayTask.h"
#include "kstationNativeNumericDisplay.h"
#include "kstationNativePanelHardware.h"
namespace kstation {
class NativeStartupDisplay final {
 using T=StartupDisplayTask;using K=T::Kind;using S=T::Stage;
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,3>CodeRanges{{{0x4358,0x438a},{0x4b5c,0x4b6a},{0x4bca,0x4c36}}};
 bool active()const{return depth_||text_.active()||panel_.active();}void reset(){depth_=0;text_.reset();panel_.reset();steps_=0;}uint64_t steps()const{return steps_;}static bool candidate(unsigned at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(NativePanelHardware::candidate(at)){if(!panel_.step(c))return false;++steps_;return true;}if(NativeNumericDisplay::candidate(at)||NativeLcdText::candidate(at)||NativeFlashState::candidate(at)){if(!text_.step(c))return false;++steps_;return true;}
  if(!depth_||boundary(jobs_[depth_-1])!=at){K k;if(at==0x4b5c)k=K::ClearSelection;else if(at==0x4358)k=K::Refresh;else if(at==0x4bca)k=K::Program;else if(at==0x4c06)k=K::Label;else return false;if(depth_==jobs_.size())throw std::logic_error("Native K startup display capacity");jobs_[depth_++]=T{k};}
  auto&t=jobs_[depth_-1];if(t.awaiting())t.resume();if(at!=boundary(t))throw std::logic_error("Native K startup display boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(t);auto cr=credits(t,c,len);auto cost=t.nextClocks(cr);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(t,c);
  t.advanceBefore(cost,cr,[&]{unsigned address=readAddress(t);unsigned r=t.stage()==S::ReadMode||t.stage()==S::ReadBank?14:8;c.reg8(r)=c.read8(int(address));val(c,c.reg8(r));return uint8_t(c.reg8(r));},[&](unsigned value){c.write8(int8_t(value),t.kind()==K::ClearSelection?0xce1d:0xcd7f);val(c,c.reg8(8));});
  if(c.cycles-begin!=cost)throw std::logic_error("Native K startup display clocks differ");if(t.complete())--depth_;else if(!t.awaiting())c.pc=c.makepc(boundary(t));++steps_;return true;}
private:
 static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static unsigned readAddress(const T&t){switch(t.stage()){case S::ReadMode:return 0xbb0e;case S::ReadEdit:case S::ReadEditMode:return 0xcd7c;case S::ReadSelection:return 0xcd7f;case S::ReadDemo:return 0xcd77;case S::ReadBank:return 0xcd82;case S::ReadProgram:return 0xcd83;case S::ReadWriteMode:return 0xcd7b;default:return 0;}}
 static unsigned boundary(const T&t){switch(t.stage()){case S::Retain:return 0x4b5c;case S::Clear:return 0x4b5e;case S::Publish:return 0x4b60;case S::Restore:return 0x4b66;case S::Return:return t.kind()==K::ClearSelection?0x4b68:0x4c04;case S::BindProgram:return 0x4358;case S::ReadMode:return 0x435e;case S::SetMode:return 0x4366;case S::ReadEdit:return 0x436a;case S::SelectEdit:return 0x4370;case S::ClearHigh:return 0x4374;case S::ReadSelection:return 0x4376;case S::SelectSelection:return 0x437c;case S::TestMode:return 0x4380;case S::SelectMode:return 0x4382;case S::OtherMode:return 0x4386;case S::BindLabel:return 0x4bca;case S::ReadDemo:return 0x4bd0;case S::SelectDemo:return 0x4bd6;case S::BindDemo:return 0x4bd8;case S::DemoText:return 0x4bde;case S::SkipLabel:return 0x4be2;case S::LabelChild:return 0x4be4;case S::ReadBank:return 0x4be6;case S::AsciiBank:return 0x4bec;case S::BankCharacter:return 0x4bee;case S::ReadProgram:return 0x4bf2;case S::ProgramNumber:return 0x4bf8;case S::ClearSelection:return 0x4bfc;case S::WriteSelection:return 0x4bfe;case S::ReadWriteMode:return 0x4c06;case S::SelectWriteMode:return 0x4c0c;case S::BindWrite:return 0x4c0e;case S::DecrementWriteMode:return 0x4c14;case S::SelectWriteLabel:return 0x4c16;case S::BindOverwrite:return 0x4c1a;case S::OverwriteTail:return 0x4c20;case S::ReadEditMode:return 0x4c24;case S::SelectEditMode:return 0x4c2a;case S::BindCursor:return 0x4c2c;case S::CursorTail:return 0x4c2e;case S::LabelTail:return 0x4c32;default:return 0;}}
 static unsigned bytes(const T&t){switch(t.stage()){case S::ReadMode:return 8;case S::ReadEdit:case S::ReadSelection:case S::ReadDemo:case S::ReadBank:case S::ReadProgram:case S::ReadWriteMode:case S::ReadEditMode:case S::BindProgram:case S::BindLabel:case S::BindDemo:case S::BindWrite:case S::BindOverwrite:case S::Publish:case S::WriteSelection:return 6;case S::SetMode:case S::DemoText:case S::BankCharacter:case S::ProgramNumber:case S::SelectEdit:case S::SelectSelection:case S::SelectMode:case S::OtherMode:case S::SelectWriteLabel:case S::OverwriteTail:case S::CursorTail:case S::LabelTail:return 4;default:return 2;}}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const T&t,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);cr.read=bus(readAddress(t),1,last);cr.write=bus(t.kind()==K::ClearSelection?0xce1d:0xcd7f,1,c.writeHistory());return cr;}
 static void project(const T&t,Stage1Cpu&c){if(t.stage()==S::SelectEdit||t.stage()==S::SelectSelection||t.stage()==S::SelectMode||t.stage()==S::OtherMode||t.stage()==S::SelectWriteLabel||t.stage()==S::OverwriteTail||t.stage()==S::CursorTail||t.stage()==S::LabelTail)c.clockI(2);switch(t.stage()){case S::Retain:c.setSP(c.getSP()-2);c.write16(c.reg16(0),int(c.getSP()));val(c,c.reg16(0));c.clockI(2);break;case S::Clear:c.reg8(8)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case S::Restore:c.reg16(0)=int16_t(c.read16(int(c.getSP())));c.setSP(c.getSP()+2);val(c,c.reg16(0));c.clockI(2);break;case S::Return:midi_projection::ret(c);break;case S::BindProgram:c.reg32(0)=0xba5c;val(c,c.reg32(0));break;case S::SetMode:midi_projection::call(c,0x2266,0x436a,true);break;case S::SelectEdit:if(t.value())c.pc=c.makepc(0x496a);break;case S::ClearHigh:c.reg8(6)=0;val(c,0);break;case S::SelectSelection:if(t.value())c.pc=c.makepc(0x4062);break;case S::TestMode:val(c,c.reg8(14));break;case S::SelectMode:c.pc=c.makepc(t.mode()?0x4386:0x4bca);break;case S::OtherMode:c.pc=c.makepc(0x4554);break;case S::BindLabel:case S::BindDemo:case S::BindWrite:case S::BindOverwrite:c.reg32(6)=t.stage()==S::BindLabel?0xbe76:t.stage()==S::BindDemo?0xbe66:t.stage()==S::BindWrite?0xbe94:0xbea3;val(c,c.reg32(6));break;case S::DemoText:midi_projection::call(c,0x239e,0x4be2,true);break;case S::LabelChild:midi_projection::call(c,0x4c06,0x4be6,false);break;case S::AsciiBank:c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),0x30,8,false));break;case S::BankCharacter:midi_projection::call(c,0x237e,0x4bf2,true);break;case S::ProgramNumber:midi_projection::call(c,0x12b6,0x4bfc,true);break;case S::ClearSelection:c.reg8(8)=0;val(c,0);break;case S::DecrementWriteMode:{int old=c.reg8(8),v=old-1;val(c,v);if((old&~v)&128)c.ccr|=2;c.reg8(8)=int8_t(v);break;}case S::SelectWriteLabel:if(!t.value())c.pc=c.makepc(0x239e);break;case S::OverwriteTail:case S::LabelTail:c.pc=c.makepc(0x239e);break;case S::BindCursor:c.reg8(14)=int8_t(0x8d);val(c,c.reg8(14));break;case S::CursorTail:c.pc=c.makepc(0x237e);break;default:break;}}
 std::array<T,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;NativeNumericDisplay text_;NativePanelHardware panel_;
};
}
